'use client';

import React, { useRef, useState, useEffect, MouseEvent } from 'react';
import CategoryCard from './CategoryCard';
import './HorizontalScrollContainer.css';

export interface CategoryData {
  id: string | number;
  label: string;
  icon?: string;
  active?: boolean;
}

interface HorizontalScrollContainerProps {
  items?: CategoryData[];
  scrollAmount?: number;
  onSelectCategory?: (item: CategoryData) => void;
}

const defaultCategories: CategoryData[] = [
  { id: 1, label: 'مُستحسَن', active: true },
  { id: 2, label: 'Temu Season Clearance', icon: '🏷️' },
  { id: 3, label: 'Top 100 Bestsellers', icon: '🔥' },
  { id: 4, label: 'Flash Sale', icon: '⚡' },
  { id: 5, label: 'Best Value' },
  { id: 6, label: 'Home Garden' },
  { id: 7, label: 'Hobbies Leisure' },
  { id: 8, label: 'Apparel' },
  { id: 9, label: 'Sports Fitness' },
];

export const HorizontalScrollContainer: React.FC<HorizontalScrollContainerProps> = ({
  items = defaultCategories,
  scrollAmount = 300,
  onSelectCategory,
}) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const [showLeftBtn, setShowLeftBtn] = useState<boolean>(false);
  const [showRightBtn, setShowRightBtn] = useState<boolean>(false);
  const [isMouseDown, setIsMouseDown] = useState<boolean>(false);
  const [startX, setStartX] = useState<number>(0);
  const [scrollLeft, setScrollLeft] = useState<number>(0);
  const [selectedId, setSelectedId] = useState<string | number>(
    items.find((i) => i.active)?.id || items[0]?.id
  );

  const checkScrollPosition = () => {
    if (!containerRef.current) return;
    const { scrollLeft, scrollWidth, clientWidth } = containerRef.current;
    setShowLeftBtn(scrollLeft > 0);
    setShowRightBtn(scrollWidth > clientWidth && Math.ceil(scrollLeft + clientWidth) < scrollWidth);
  };

  useEffect(() => {
    const container = containerRef.current;
    if (container) {
      checkScrollPosition();
      container.addEventListener('scroll', checkScrollPosition);
      window.addEventListener('resize', checkScrollPosition);
    }
    return () => {
      if (container) {
        container.removeEventListener('scroll', checkScrollPosition);
      }
      window.removeEventListener('resize', checkScrollPosition);
    };
  }, [items]);

  const handleScroll = (direction: 'left' | 'right') => {
    if (!containerRef.current) return;
    const offset = direction === 'left' ? -scrollAmount : scrollAmount;
    containerRef.current.scrollBy({ left: offset, behavior: 'smooth' });
  };

  const handleMouseDown = (e: MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current) return;
    setIsMouseDown(true);
    setStartX(e.pageX - containerRef.current.offsetLeft);
    setScrollLeft(containerRef.current.scrollLeft);
  };

  const handleMouseLeaveOrUp = () => setIsMouseDown(false);

  const handleMouseMove = (e: MouseEvent<HTMLDivElement>) => {
    if (!isMouseDown || !containerRef.current) return;
    e.preventDefault();
    const x = e.pageX - containerRef.current.offsetLeft;
    const walk = (x - startX) * 1.5;
    containerRef.current.scrollLeft = scrollLeft - walk;
  };

  const handleItemClick = (item: CategoryData) => {
    setSelectedId(item.id);
    if (onSelectCategory) onSelectCategory(item);
  };

  return (
    <div className="scroll-wrapper">
      {showLeftBtn && (
        <button className="scroll-btn left-btn" onClick={() => handleScroll('left')}>
          &#10094;
        </button>
      )}

      <div
        className={`horizontal-scroll-container ${isMouseDown ? 'dragging' : ''}`}
        ref={containerRef}
        onMouseDown={handleMouseDown}
        onMouseLeave={handleMouseLeaveOrUp}
        onMouseUp={handleMouseLeaveOrUp}
        onMouseMove={handleMouseMove}
      >
        <div className="scroll-content">
          {items.map((item) => (
            <CategoryCard
              key={item.id}
              id={item.id}
              label={item.label}
              icon={item.icon}
              isActive={selectedId === item.id}
              onClick={() => handleItemClick(item)}
            />
          ))}
        </div>
      </div>

      {showRightBtn && (
        <button className="scroll-btn right-btn" onClick={() => handleScroll('right')}>
          &#10095;
        </button>
      )}
    </div>
  );
};

export default HorizontalScrollContainer;